add('waffle','''${box-sizing:border-box;display:grid;grid-template-columns:1fr;align-content:center;justify-items:center;gap:var(--gap);padding:var(--gap);container-type:inline-size} $ .units{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));width:100%;gap:4px} $ .u{aspect-ratio:1;background:var(--n-2)} $ .u.on{background:var(--a1-7)} $ .u.tone-2{background:var(--a2)} $ .fig{font-size:var(--type-52);font-weight:var(--figure-weight);line-height:var(--figure-line);margin:0} $ .name{font-size:var(--type-24);font-weight:var(--name-weight);margin:0} $.figures .u{clip-path:polygon(35% 0,65% 0,70% 20%,60% 32%,85% 38%,90% 62%,70% 62%,68% 100%,53% 100%,50% 72%,47% 100%,32% 100%,30% 62%,10% 62%,15% 38%,40% 32%,30% 20%)} @container(max-width:400px){$ .fig{font-size:var(--type-36)} $ .name{font-size:var(--type-18)}}''')
