add('positioning','''${box-sizing:border-box;position:relative;border-left:2px solid var(--ink);border-bottom:2px solid var(--ink);background:var(--n-1);container-type:size} $::before{content:"";position:absolute;top:50%;left:0;right:0;height:1px;background:var(--n-3)} $::after{content:"";position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--n-3)} $ .axis-x{position:absolute;bottom:var(--gap-sm);left:var(--gap-sm);right:var(--gap-sm);display:flex;justify-content:space-between;font-size:var(--type-16)} $ .axis-y{position:absolute;left:var(--gap-sm);top:var(--gap-sm);bottom:var(--gap-lg);display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-16)} $ .mark{box-sizing:border-box;position:absolute;left:calc(12% + var(--x)*.76%);bottom:calc(12% + var(--y)*.76%);transform:translate(-50%,50%);width:88px;height:88px;border:1px solid var(--n-3);background:var(--page);border-radius:50%;display:flex;align-items:center;justify-content:center;text-align:center;padding:var(--gap-sm);z-index:1} $ .mark.on{background:var(--a1-7);color:var(--page)} $ .name{font-size:var(--type-18);font-weight:var(--name-weight);margin:0} $ .seat.logo{width:52px;height:52px} @container(max-width:550px){$ .mark{width:64px;height:64px} $ .name{font-size:var(--type-14)}}''')
add('network','''${position:relative;container-type:size} $ .node{position:absolute;left:calc(10% + var(--x)*.8%);top:calc(12% + var(--y)*.76%);transform:translate(-50%,-50%);width:90px;height:90px;box-sizing:border-box;padding:var(--gap-sm);background:var(--n-2);border:1px solid var(--n-4);border-radius:50%;display:flex;align-items:center;justify-content:center;text-align:center;z-index:2} $ .node.on{background:var(--a1-7);color:var(--page);border-color:var(--a1-7)} $ .name{font-size:var(--type-18);font-weight:var(--name-weight);margin:0} $ .link{position:absolute;left:calc(10% + var(--x1)*.8%);top:calc(12% + var(--y1)*.76%);height:1px;width:calc(hypot((var(--x2) - var(--x1))*.8,(var(--y2) - var(--y1))*.76)*1%);background:var(--n-4);transform-origin:left center;transform:rotate(atan2(calc((var(--y2) - var(--y1))*.76),calc((var(--x2) - var(--x1))*.8)));z-index:1} $ .link.strong{height:3px;background:var(--a1-7)} @container(max-width:550px){$ .node{width:64px;height:64px} $ .name{font-size:var(--type-14)}}''')
