assert len(D)==56,(len(D),set(x.name for x in E.iterdir())-D.keys())
for el,css in D.items():
 root='[data-el="crossrail-'+el+'"]'
 # Root qualifier special cases are represented as $.root. Others use data-el alone valid and scoped.
 css=css.replace('$',root)
 put(E/el/'element.css',css)
 put(E/el/'description.md',f'Crossrail {el.replace("-"," ")} keeps the source deck’s disciplined alignment, thin structural rules, generous neutral space and a single deep ranked accent. Shapes remain crisp; round forms are reserved for figures, relationships and outline capsules. Text keeps a stable hierarchy and steps down within narrower containers.')
 m=json.loads((E/el/'element.json').read_text());m['tokenDefaults']={'--crossrail-angle':'0deg'} if el in ['cycle','hub','radar'] else {};put(E/el/'element.json',json.dumps(m,indent=2))
print('Crossrail kit, foundation, 56 original CSS elements written')
